buggy.buggy_any_all_numeric_na_fill:
import pandas as pd
import numpy as np
from pandas.arrays import SparseArray
import traceback

# Test case 1: Int64 with any(skipna=False)
try:
    arr = SparseArray(pd.array([1, None], dtype='Int64'))
    result = arr.any(skipna=False)
    probe('int64_any_result', result)
except TypeError as e:
    if 'ambiguous' in str(e):
        probe('int64_any_typeerror', 1)
    else:
        raise
except Exception as e:
    probe('int64_any_other_error', str(e))

# Test case 2: Float64 with all(skipna=False)
try:
    arr = SparseArray(pd.array([1, 0, None], dtype='Float64'))
    result = arr.all(skipna=False)
    probe('float64_all_result', result)
except TypeError as e:
    if 'ambiguous' in str(e):
        probe('float64_all_typeerror', 1)
    else:
        raise
except Exception as e:
    probe('float64_all_other_error', str(e))

# Test case 3: astype path - int64 to SparseDtype with pd.NA
try:
    arr = SparseArray(np.array([1, 0, 0], dtype='int64'), fill_value=0)
    arr_converted = arr.astype(pd.SparseDtype('int64', pd.NA))
    result = arr_converted.any(skipna=False)
    probe('astype_int64_any_result', result)
except TypeError as e:
    if 'ambiguous' in str(e):
        probe('astype_int64_any_typeerror', 1)
    else:
        raise
except Exception as e:
    probe('astype_int64_any_other_error', str(e))

# Test case 4: bool subtype with pd.NA (should still raise TypeError)
try:
    arr = SparseArray([True, False, False], fill_value=False)
    arr_converted = arr.astype(pd.SparseDtype(bool, pd.NA))
    result = arr_converted.any(skipna=False)
    probe('bool_any_result', result)
except TypeError as e:
    if 'ambiguous' in str(e):
        probe('bool_any_typeerror', 1)
    else:
        raise
except Exception as e:
    probe('bool_any_other_error', str(e))

